from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove any spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and extract each collection of nested parentheses
    collections = []
    current_collection = ""
    for char in paren_string:
        if char == "(":
            current_collection += char
        elif char == ")":
            current_collection += char
            collections.append(current_collection)
            current_collection = ""

    # Step 3: Check if each collection is balanced with no overlapping
    def is_balanced(collection):
        stack = []
        for char in collection:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack or stack[-1] != "(":
                    return False
                stack.pop()
        return not stack

    balanced_collections = [collection for collection in collections if is_balanced(collection)]

    # Step 4: Separate each collection into distinct strings
    distinct_strings = []
    for collection in balanced_collections:
        distinct_string = ""
        for char in collection:
            if char == "(":
                distinct_string += char
            elif char == ")":
                distinct_string += char
                distinct_strings.append(distinct_string)
                distinct_string = ""

    # Step 5: Return the list of distinct strings
    return distinct_strings

